%% ANVL project: the Rocq-to-Core-Erlang extraction test pipeline.
%%
%% dune remains the source of truth for the OCaml plugin and the Rocq
%% theories. One project, two OTP apps:
%%  - `extracted' (test/extracted): the .core modules generated by the
%%    pre-compile hook (rocq c); anvl_erlc compiles them with the
%%    from_core option, which it adds automatically for *.core sources
%%  - `rocq_core_erlang_tests' (test): the eunit suites (*_tests.erl)
%% The `all` condition runs every suite it finds in the test app.
-export([conf/0, init/1]).

-include("anvl.hrl").

conf() ->
  #{plugins => [anvl_erlc],
    conditions => [all],
    erlang =>
      #{app_paths => ["test", "test/extracted"],
        sources => ["${src_root}/src/*.erl", "${src_root}/src/*.core"]}}.

%% Extract the .core files before the erlc sources are listed (the
%% hook may generate them). The hook fires for every app of the
%% project; only the extracted app's src dir holds the cores, so the
%% others make it a no-op.
init(This) ->
  anvl_erlc:add_pre_compile_hook(
    This,
    fun(#{src_root := SrcRoot}) ->
        %% only the extracted app's src dir holds the cores; the hook
        %% is a no-op for the other apps of the project
        case filelib:is_file(
               filename:join([SrcRoot, "src", "extracted.app.src"])) of
          true  -> precondition(cores_extracted());
          false -> false
        end
    end).

%% Repo root: this is the root project
repo_root() -> anvl_project:root_dir().

theories_dir() ->
  filename:join(repo_root(), "_build/default/theories").

plugin_dir() ->
  filename:join([repo_root(), "test", "plugin"]).

test_dir() -> filename:join(repo_root(), "test").

%% src dir of the `extracted' app: where rocq writes the .core files
extracted_src_root() ->
  filename:join([repo_root(), "test", "extracted", "src"]).

v_files() ->
  filelib:wildcard(filename:join(test_dir(), "*.v")).

?MEMO(build_inputs,
      begin
        %% Plugin + theories: dune decides what to rebuild
        _ = anvl_lib:exec("dune", ["build"], [{cd, repo_root()}]),
        false
      end).

%% One test/<base>.v -> <extracted app>/src/<base>.core
?MEMO(core_extracted, VFile,
      begin
        _ = precondition(build_inputs()),
        Core = filename:join(
                 [extracted_src_root(),
                  filename:rootname(filename:basename(VFile)) ++ ".core"]),
        anvl_lib:newer(VFile, Core)
          andalso begin
            %% rocq resolves the CoreErlang Extraction "base" argument
            %% relative to its cwd, so run it inside the src dir
            _ = anvl_lib:exec(
                  "rocq",
                  ["c", "-q",
                   "-I", plugin_dir(),
                   "-Q", theories_dir(), "Erlang",
                   VFile],
                  [{cd, extracted_src_root()}]),
            true
          end
      end).

%% All .v files extracted, one condition (and one rocq process) per file
?MEMO(cores_extracted,
      precondition([core_extracted(VFile) || VFile <- v_files()])).

%% Compile both apps (in this order: the suites may call the
%% extracted modules)
?MEMO(compile,
      precondition(
        [ anvl_erlc:app_compiled(default, extracted),
          anvl_erlc:app_compiled(default, rocq_core_erlang_tests)
        ])).

%% Run every *_tests module of the test app. anvl_erlc may have loaded
%% older module versions into this node while analyzing them, so the
%% code server cache is purged and reloaded from the beam files first.
?MEMO(all,
      begin
        _ = precondition(compile()),
        CoreEbin = filename:join(anvl_erlc:app_path(default, extracted), "ebin"),
        SuiteEbin = filename:join(anvl_erlc:app_path(default, rocq_core_erlang_tests), "ebin"),
        lists:foreach(
          fun(Ebin) ->
              true = code:add_patha(Ebin),
              lists:foreach(
                fun(Beam) ->
                    M = list_to_atom(filename:rootname(filename:basename(Beam))),
                    _ = code:purge(M),
                    _ = code:delete(M),
                    {module, M} = code:ensure_loaded(M)
                end, filelib:wildcard(filename:join(Ebin, "*.beam")))
          end, [CoreEbin, SuiteEbin]),
        [_ | _] = Suites =
          [ list_to_atom(filename:rootname(filename:basename(Beam)))
            || Beam <- filelib:wildcard(filename:join(SuiteEbin, "*_tests.beam")) ],
        case eunit:test(Suites, [verbose]) of
          ok -> true;
          error -> exit(unsat)
        end
      end).
